import{_ as t,a as o}from"./chunks/b7df1ad96d20e999caa8.zJmjEnrD.js";import{_ as a,o as i,c as r,a5 as n}from"./chunks/framework.DNkHA0lr.js";const f=JSON.parse('{"title":"Solve Your Own Problems & Sell The Solution","description":"","frontmatter":{"title":"Solve Your Own Problems & Sell The Solution","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-self-reliant-career-path-how-to-generate-independent-income.md","filePath":"en/letters/the-self-reliant-career-path-how-to-generate-independent-income.md"}'),s={name:"en/letters/the-self-reliant-career-path-how-to-generate-independent-income.md"};function l(p,e,h,u,d,c){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="solve-your-own-problems-sell-the-solution" tabindex="-1">Solve Your Own Problems &amp; Sell The Solution <a class="header-anchor" href="#solve-your-own-problems-sell-the-solution" aria-label="Permalink to &quot;Solve Your Own Problems &amp; Sell The Solution&quot;">​</a></h1><p>Dan Koe · 2023-04-22 · <a href="https://thedankoe.com/letters/the-self-reliant-career-path-how-to-generate-independent-income/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-self-reliant-career-path-how-to-generate-independent-income">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/GmHQGVD7KRQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>The creator economy is a decentralized society where people can learn, teach, and create a better life for themselves.</p><p>I made this realization over the past decade.</p><p>When I was a child, I didn’t trust the school system (or my parents) to equip me with the knowledge necessary to make the most of my life.</p><p>Instead, I consumed content from YouTubers, bloggers, and social media accounts that were teaching about fitness, business, and philosophy.</p><p>I bought affordable courses that taught me more than my overpriced college degree.</p><p>My college degree got me into a $60K/year job.</p><p>My internet studies built me a business that enables me to do anything I want in this life.</p><p>Education is only one aspect of the creator economy.</p><p>I see it as a self-sufficient Utopia that is the product of human desire and evolution.</p><p>I have a person that sells shoes.</p><p>I have a person that sells kitchenware.</p><p>I have a person that sells blue light glasses.</p><p>I have a person that sells apparel.</p><p>I have a person that sells coffee and supplements.</p><p>I have a person that sells fresh herbs, milk, and meat.</p><p>All of which have an underlying philosophy that holds more depth than today’s shallow brands and mega corporations that just want your money.</p><p>This thread is a prime example of what I mean:</p><blockquote><p>This is why I made the Sol short\\</p><p>A classic, short-inseam 100% cotton short that was flexible, comfortable and looked stylish paired with whatever on top.\\</p><p>Couldn’t find it, so I made it. <a href="https://t.co/vB85NhzpCH" target="_blank" rel="noreferrer">https://t.co/vB85NhzpCH</a></p><p>— 🌞 Sol Brah 🌞 (@SolBrah) <a href="https://twitter.com/SolBrah/status/1649604730426126338?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 22, 2023</a></p></blockquote><p>And, of course, I have plenty of individuals that I can acquire specific knowledge from in relevant fields.</p><p>If I want to learn stock or real estate investing, I can acquire that knowledge for a fraction of what it would cost from a degree. And I would get 10x the results because the person teaching it actually has results.</p><p>The creator economy is where you:</p><ul><li>Find people with shared goals</li><li>Curate your own community</li><li>Provide value to that community</li><li>Get paid for your contributions</li></ul><p>My recommendation is to start with what we’ve learned in previous letters.</p><p>Start an education business by pursuing your purpose (because it has minimal startup costs and huge profit margins).</p><p>Create an independent income for yourself.</p><p>Then, build a business that you <em>really</em> want to build.</p><p>My little one-person education business makes around $1.5 million a year.</p><p>I am now writing a book, building software, and strategizing the true impact I want to leave on the world. I have the money and resources to do it, but only because I started with what was available to me.</p><p>I didn’t fantasize about building a billion-dollar company just to leave me paralyzed with overwhelm and anxiety.</p><p>That’s exactly how you make 0 progress.</p><p>P.S. This style of business (solving your own problems and selling the solution) is exactly what I help with in <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics.</a></p><h2 id="solve-your-problems-for-profit-purpose" tabindex="-1">Solve Your Problems For Profit &amp; Purpose <a class="header-anchor" href="#solve-your-problems-for-profit-purpose" aria-label="Permalink to &quot;Solve Your Problems For Profit &amp; Purpose&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>My entire business journey was selfish.</p><p>All I did was build for myself, write to myself, and sell to myself.</p><p>When you are the niche, saturation and competition cease to exist.</p><p>If you want to profit off of your purpose:</p><ol><li>Identify a problem in your life</li><li>Set a goal to reveal your present purpose</li><li>Experiment with different solutions</li><li>Find what works and create your own</li><li>Talk about your journey in public</li><li>Offer your solution with a price tag on it</li></ol><p>Repeating this process has been the guiding light in my life.</p><p>Ever since I can remember I’ve always had a project to build.</p><p>A project is an organized way for achieving your goal (or purpose).</p><p>A few years ago, I struggled with productivity.</p><p>It was difficult to focus and I knew that I could be doing more.</p><p>That was the problem that I became aware of.</p><p>So, I made it my purpose to fix that area of my life.</p><p>I watched YouTube videos, purchased supplements, and ordered a few different planners and journals.</p><p>I was adamant on solving the problem, so I experimented with every piece of advice I got.</p><p>After a few months, I had gotten some incredible results.</p><p>So, I sat down to create a sustainable productivity solution that would fit <em>me</em> to perfection (because there was always one minor issue with the other methods I tried).</p><p>This is when I designed and launched the digital Power Planner.</p><p>I didn’t have many followers at the time, but I loved the thought of making a living from my productivity knowledge. So, I:</p><ul><li>Wrote content on what I knew about productivity</li><li>Grew a following with the proper strategies</li><li>Promoted the digital planner as a free download</li><li>Added educational resources to the free download</li></ul><p>People loved it.</p><p>So, I took it further and launched a physical version of the planner.</p><p>Things are different now, but the entirety of my success is built on solving my own problems and selling the solution.</p><p>I solved my career problems by learning web design (so I built a course).</p><p>I solved my money problems by succeeding with freelancing (so I built another course).</p><p>Then, Modern Mastery was born from me building what I would have wanted for a community and learning platform.</p><p>Now, I’m writing a book and building a software that I could sell to my younger self (to help him reach his goals faster).</p><p>It’s that simple.</p><p>Everyone is an entrepreneur.</p><p>Some just get paid for the problems they solve.</p><h2 id="the-self-reliant-career-path-how-to-start" tabindex="-1">The Self-Reliant Career Path (How To Start) <a class="header-anchor" href="#the-self-reliant-career-path-how-to-start" aria-label="Permalink to &quot;The Self-Reliant Career Path (How To Start)&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><blockquote><p>There are almost 7B people on this planet. Someday, I hope, there will be almost 7B companies. <em>—</em> Naval</p></blockquote><p>The future of work is play and everyone will be an entrepreneur.</p><p>Everyone will be forced to create, contribute, and deliver value to their community or else their way of survival will dry up.</p><p>Artificial intelligence points to this reality.</p><p>Automation points to this reality.</p><p>Most things on the internet point to this reality.</p><p>Even if that does not become that reality for most people, it can for you.</p><h3 id="_1-profitable-interests" tabindex="-1">1) Profitable Interests <a class="header-anchor" href="#_1-profitable-interests" aria-label="Permalink to &quot;1) Profitable Interests&quot;">​</a></h3><p>We start with life direction.</p><p>You need a vision, goals, and priority tasks that you can execute on every single day.</p><p>This is how you gain experience in this life.</p><p>This is how you gain knowledge, skill, and the direction to acquire both that you can pass down to those on the same path.</p><p>All burning problems (in your life and others) fall within the eternal markets: Health, wealth, and relationships.</p><p>Self-improvement is about solving your own problems in those domains.</p><p>Business is about providing a solution to problems in those domains.</p><p>Simply by:</p><ul><li>Setting a purposeful goal to improve yourself</li><li>Self-educating and acquiring the skills for your mind, body, and business</li><li>Letting your curiosity guide which methods you choose and create</li></ul><p>You will have the experience necessary to help others and profit off of living with purpose.</p><p>Curiosity is a crucial touchpoint there.</p><p>What makes you unique is your ability to find the combination of knowledge that gets you results.</p><p>In business, some may be curious about e-commerce or website flipping.</p><p>Others may be curious about personal branding and digital products.</p><p>In health, some may be curious about sports and optimal performance.</p><p>Others may be curious about bodybuilding and biohacking.</p><p>Too often we think that we are doing the same thing as everyone else.</p><p>Your story is vastly different.</p><p>Everyone has to pursue goals in the same eternal markets. You won’t escape that. But the way you pursue those goals can be unique to you, and that’s what makes your experience profitable.</p><h3 id="_2-project-to-product" tabindex="-1"><strong>2) Project To Product</strong> <a class="header-anchor" href="#_2-project-to-product" aria-label="Permalink to &quot;**2) Project To Product**&quot;">​</a></h3><p>If you don’t know what to sell, sell something you would have wanted on your journey, or something you can’t find but want right now.</p><p>When you begin pursuing a goal, the best way to actualize it is to:</p><ul><li>Study the fundamentals to gain clarity</li><li>Start a real-world project so you don’t get trapped in tutorial hell</li><li>Build the project until you discover a problem</li><li>Buy courses, coaching, or research internet content to find the solution</li><li>Apply everything you learn until the project is completed</li></ul><p>A “project” doesn’t sound like it applies to all domains of life, but hear me out.</p><p>When you start improving your health, you only make progress when you turn it into a measurable personal project.</p><p>You go to the gym.</p><p>You write down your routine.</p><p>You document every single one of your lifts.</p><p>If you aren’t seeing progress, you research and find the gaps in your knowledge.</p><p>Maybe it’s nutrition holding you back?</p><p>Time to track your calorie intake.</p><p>Seeing progress in your physique but not in your energy?</p><p>Maybe you fall down an esoteric rabbit hole of how beef liver is the most nutrient-dense food on the planet.</p><p>So, you experiment with it and note the results.</p><p>When you treat every domain of your life as a purpose-oriented project you are required to experiment.</p><p>Through self-experimentation you create a unique set of experiences that you can pass down to others.</p><p>In marketing, you are selling purpose (purpose = goal = desired outcome).</p><p>You are selling the benefits of the lifestyle that come from pursuing that purpose.</p><p>In the health space, some people might sell a running product to <em>20-30 year olds that want to create a healthy social circle and get involved with their community</em>_._</p><p>Others may sell a weight training program to business bros that want to get jacked with only 3 days in the gym. That way they have both money and muscles so they can live a fun life. Who wouldn’t buy that (if they resonate with the product’s philosophy)?</p><p>My writing product, <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>, is my unique experience with personal branding and gaining millions of followers through digital writing.</p><p>I experimented with idea generation, newsletter writing, and social media content over the course of 2-3 years.</p><p>You don’t have to wait that long.</p><p>I actually recommend launching immediately.</p><p>You need <em>data</em> and <em>feedback</em> as to how to make your products better.</p><p>The benefits you reap from living with purpose are your marketing firepower to help people live better lives.</p><p>That is, the underlying philosophy you forge through self-experimentation is how you generate a creative income from your pursuits.</p><h3 id="_3-personal-distribution-center" tabindex="-1">3) Personal Distribution Center <a class="header-anchor" href="#_3-personal-distribution-center" aria-label="Permalink to &quot;3) Personal Distribution Center&quot;">​</a></h3><p>This all sounds great so far.</p><ol><li>Study your interests to actualize your goals</li><li>Experiment with a personal project to get results</li><li>Turn that project into a product you can sell with purpose</li></ol><p>But most people get stuck there.</p><p>They don’t realize that you need both a product and <em>people</em> to actually make money.</p><p>You have to build <em>distribution.</em></p><p>This isn’t optional.</p><p>My favorite way to do this is by building a personal brand.</p><p>One, because it’s becoming a necessity.</p><p>Brands, companies, and employers alike are hiring based on your public resume (your profile).</p><p>Two, the following you gain is leverage.</p><p>You can pivot as your life does and sell anything you want (<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">as long as you don’t box yourself into one narrow niche</a>).</p><p>Three, most other forms of distribution leave you with nothing.</p><p>Paid ads and cold outreach are extremely powerful, but what happens when you stop doing them?</p><p>Do you have an audience or email list that was built along the way?</p><p>Can you ever take a break?</p><p>Can you cultivate a meaningful philosophy behind your brand and not be limited in the products you sell?</p><p>Maybe, but it’s not likely.</p><p>Build a personal distribution center by:</p><ul><li>Passing down the lessons you learn pursuing your goals</li><li>Writing out your thoughts, beliefs, and opinions to separate yourself from others</li><li>Teaching what you learn in a persuasive manner</li></ul><p>That’s really it.</p><p>There are technical details and <a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">nuanced strategies for social media growth</a>… but that’s a goal and project that you can experiment with for yourself.</p><p>(That’s how you start learning every marketable skill there is, by building your business and applying what you learn to it).</p><p>This is the future career path.</p><p>This is how you monetize close to everything you learn.</p><p>This is how you get paid for just living.</p><p>The future belongs to people that pass down their valuable experiences to improve others’ lives.</p><p>That’s what all the best businesses do, just take a look at the next social media post you see (from the lens of a creator, not a consumer) and you can verify this for yourself.</p><p>Join in on the self-sufficient and growing utopia that is the creator economy and thank me later.</p><p>– Dan</p>',152)])])}const g=a(s,[["render",l]]);export{f as __pageData,g as default};
